import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Android & Capacitor","description":"","frontmatter":{},"headers":[],"relativePath":"domains/android-capacitor.md","filePath":"domains/android-capacitor.md","lastUpdated":1787839527000}'),i={name:"domains/android-capacitor.md"};function d(n,a,s,l,c,h){return t(),r("div",null,[...a[0]||(a[0]=[o(`<h1 id="android-capacitor" tabindex="-1">Android &amp; Capacitor <a class="header-anchor" href="#android-capacitor" aria-label="Permalink to &quot;Android &amp; Capacitor&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>StrawMoneyBook 以 <strong>Capacitor 8</strong> 包裝 Vue SPA 為 Android App，並透過原生 plugin 整合 Google Identity、SQLite SQLCipher、桌面小工具、Wear OS companion、安全鎖與銀行自動化等能力。</p><h2 id="capacitor-架構" tabindex="-1">Capacitor 架構 <a class="header-anchor" href="#capacitor-架構" aria-label="Permalink to &quot;Capacitor 架構&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  WebLayer[Vue WebView]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CapPlugins[Capacitor Plugins]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Native[Android Java/Kotlin]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Wear[:wear Compose Module]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  WebLayer --&gt; CapPlugins</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CapPlugins --&gt; Native</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Native --&gt; Wear</span></span></code></pre></div><p>入口：<a href="https://github.com/StrawCoding/StrawMoneyBook/tree/main/frontend/android" target="_blank" rel="noreferrer"><code>frontend/android/</code></a></p><h2 id="本機資料-android" tabindex="-1">本機資料（Android） <a class="header-anchor" href="#本機資料-android" aria-label="Permalink to &quot;本機資料（Android）&quot;">​</a></h2><ul><li>SQLCipher 加密：<code>straw_money_bookSQLite.db</code></li><li>初始化：Capacitor SQLite plugin + <a href="/architecture/startup-and-runtime.html"><code>bootstrap.service.js</code></a></li><li>plugin-null 時只重試 primary DB，禁止切空 recovery DB（smb298）</li></ul><h2 id="原生-plugin-節錄" tabindex="-1">原生 Plugin（節錄） <a class="header-anchor" href="#原生-plugin-節錄" aria-label="Permalink to &quot;原生 Plugin（節錄）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plugin / 類別</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/android/app/src/main/java/com/strawcoding/strawmoneybook/GoogleIdentityPlugin.java" target="_blank" rel="noreferrer"><code>GoogleIdentityPlugin.java</code></a></td><td>Google 登入、server auth code</td></tr><tr><td><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/android/app/src/main/java/com/strawcoding/strawmoneybook/MainActivity.java" target="_blank" rel="noreferrer"><code>MainActivity.java</code></a></td><td>OAuth result 轉送</td></tr><tr><td>HomeWidget plugin</td><td>5 種桌面小工具</td></tr><tr><td>Local Notifications</td><td>記帳提醒</td></tr></tbody></table><h2 id="桌面小工具" tabindex="-1">桌面小工具 <a class="header-anchor" href="#桌面小工具" aria-label="Permalink to &quot;桌面小工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>用途</th><th>點擊導向</th></tr></thead><tbody><tr><td><code>StrawMoneyWidgetProvider</code></td><td>月收支總覽</td><td><code>/analysis</code></td></tr><tr><td><code>StrawMoneyPieChartWidgetProvider</code></td><td>圓餅圖</td><td><code>/analysis</code></td></tr><tr><td><code>StrawMoneyBarChartWidgetProvider</code></td><td>長條圖</td><td><code>/analysis</code></td></tr><tr><td><code>StrawMoneyQuickAddWidgetProvider</code></td><td>快速記帳</td><td><code>/transactions/quick-add</code></td></tr><tr><td><code>StrawMoneyAiBookkeepingWidgetProvider</code></td><td>AI 記帳</td><td><code>/ai-auto-bookkeeping</code></td></tr></tbody></table><p>資料由 <a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/ui/services/home-widget.service.js" target="_blank" rel="noreferrer"><code>home-widget.service.js</code></a> 寫入 SharedPreferences，原生繪製 Bitmap。</p><h2 id="wear-os-companion" tabindex="-1">Wear OS Companion <a class="header-anchor" href="#wear-os-companion" aria-label="Permalink to &quot;Wear OS Companion&quot;">​</a></h2><ul><li>獨立 <code>:wear</code> Compose 模組 + Tile</li><li>MessageClient <code>/smb/v1/*</code> nearby-first，寫入同一 SQLCipher DB（不經 WebView）</li><li>Room outbox v2；Wear Compose <strong>1.6.2</strong>（禁 1.4.x + targetSdk≥35 閃退）</li><li>Play 測試 / 正式分軌上傳（phone + wear 各一 AAB）；預設測試軌道 <strong>internal</strong>（未拍板不改 <code>play-testing-channel.json</code>）</li><li>長表單 route 使用 <code>meta.hideAppChrome</code>（quick-add、報表列印等），BottomNav 不遮 CTA</li></ul><p>詳見 <a href="/operations/wear-companion.html">Wear Companion</a>、<a href="/operations/playwright-app-shell.html">Playwright App Shell</a>。</p><h2 id="安全與-ux" tabindex="-1">安全與 UX <a class="header-anchor" href="#安全與-ux" aria-label="Permalink to &quot;安全與 UX&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>Service</th></tr></thead><tbody><tr><td>生物辨識鎖</td><td><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/ui/services/security-lock.service.js" target="_blank" rel="noreferrer"><code>security-lock.service.js</code></a></td></tr><tr><td>Android 返回鍵</td><td><a href="/architecture/startup-and-runtime.html"><code>app-runtime.service.js</code></a></td></tr><tr><td>語音輸入</td><td>AI 記帳整合 Capacitor speech</td></tr><tr><td>主題 / modern UI</td><td><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/ui/services/theme.service.js" target="_blank" rel="noreferrer"><code>theme.service.js</code></a>、<a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/ui/assets/css/apple-ui.css" target="_blank" rel="noreferrer"><code>apple-ui.css</code></a></td></tr></tbody></table><h2 id="web-測試版" tabindex="-1">Web 測試版 <a class="header-anchor" href="#web-測試版" aria-label="Permalink to &quot;Web 測試版&quot;">​</a></h2><p>Production web SPA：<code>https://www.strawmb.com/app/</code>（hash router，<code>VITE_WEB_HASH_ROUTER=true</code>），連 <code>api.strawmb.com</code>。本機 <code>npm run dev</code> 亦預設連營運 API。</p><h2 id="與其他域" tabindex="-1">與其他域 <a class="header-anchor" href="#與其他域" aria-label="Permalink to &quot;與其他域&quot;">​</a></h2><ul><li><a href="/guide/authentication.html">Authentication</a> — Google Identity、server auth code</li><li><a href="/domains/bank-sync-einvoice.html">Bank Sync</a> — 原生銀行自動化</li><li><a href="/domains/bookkeeping.html">Bookkeeping</a> — Wear 記帳寫入同一 DB</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/guide/frontend-stack.html">Frontend Stack</a></li><li><a href="/architecture/startup-and-runtime.html">Startup &amp; Runtime</a></li></ul>`,24)])])}const m=e(i,[["render",d]]);export{u as __pageData,m as default};
